#!/bin/bash
# KV-CORES-R2/INGEST 10-27: run_kit_kv.sh front half only (lint, sdc_lint, selrange, adder map, ORFS synth, DONT_USE
# check, core_preflight face_guard on 1_2_yosys.v + synth ODB). Stops before floorplan: NO P&R.
K=$(cd "$1" && pwd); MEM=${2:-24}; CPUS=${3:-8}
docker run --rm --name kvingest-r2-face-$$ --cpus=$CPUS --memory=${MEM}g --memory-swap=${MEM}g -v "$K":/work   -w /OpenROAD-flow-scripts/flow openroad/orfs:asap7lock bash -lc "source /OpenROAD-flow-scripts/env.sh >/dev/null 2>&1;   M='make DESIGN_CONFIG=/work/config.mk WORK_HOME=/work/run FLOW_VARIANT=base NUM_CORES=$CPUS'; PD=/OpenROAD-flow-scripts/flow/platforms/asap7;   python3 -I /work/rtl_lint.py /work > /work/rtl_lint.log 2>&1; rc=\$?; tail -1 /work/rtl_lint.log;   if [ \$rc = 0 ]; then python3 -I /work/sdc_lint.py /work --liberty \$(ls \$PD/lib/NLDM/asap7sc7p5t_*RVT_*.lib* | grep -v FAKE) > /work/sdc_lint.log 2>&1; rc=\$?; tail -1 /work/sdc_lint.log; fi;   if [ \$rc = 0 ]; then python3 -I /work/selrange_gate.py /work --out /work/selrange.json > /work/selrange.log 2>&1; s=\$?; tail -1 /work/selrange.log; [ \$s = 1 ] && rc=1; fi;   if [ \$rc = 0 ] && grep -q '^export ADDER_MAP_FILE = /work/adder_map_dontuse.v' /work/config.mk; then python3 -I /work/adder_map_dontuse.py gen --platform-dir \$PD --out /work/adder_map_dontuse.v --report /work/adder_map_dontuse.json; rc=\$?; fi;   if [ \$rc = 0 ]; then \$M synth > /work/synth_make.log 2>&1; rc=\$?; tail -2 /work/synth_make.log; fi;   N=\$(ls /work/run/results/asap7/*/base/1_2_yosys.v 2>/dev/null | tail -1);   if [ \$rc = 0 ]; then python3 -I /work/adder_map_dontuse.py check --platform-dir \$PD --netlist \$N --report /work/dont_use_check.json; echo dont_use rc=\$?; fi;   if [ \$rc = 0 ]; then python3 -I /work/core_preflight.py /work \$N --out /work/face_guard.json > /work/face_guard.log 2>&1; echo face_guard rc=\$?; tail -3 /work/face_guard.log;     D=\$(ls /work/run/results/asap7/*/base/1_synth.odb 2>/dev/null | tail -1); printf 'read_db %s\\nwrite_verilog /work/1_synth_odb.v\\n' \$D > /work/synth_odb_v.tcl; openroad -exit /work/synth_odb_v.tcl > /work/synth_odb_v.log 2>&1 &&     python3 -I /work/core_preflight.py /work /work/1_synth_odb.v --out /work/face_guard_odb.json > /work/face_guard_odb.log 2>&1; echo face_guard_odb rc=\$?; tail -1 /work/face_guard_odb.log; fi;   chown -R 1000:1000 /work; exit \$rc"
